SELECT fn_cp_import_case('biens-recel-vente-en-ligne', '{"slug": "biens-recel-vente-en-ligne", "title": "Il a acheté le vélo cent euros sur une annonce et l''a revendu", "theme_slug": "atteintes-biens", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 16 heures. Un homme se présente au commissariat après avoir été identifié comme ayant revendu un vélo haut de gamme dont l''acquéreur final a découvert qu''il s''agissait d''un bien volé, expliquant avoir lui-même acheté ce vélo cent euros sur une annonce en ligne, une somme qu''il reconnaît volontiers comme dérisoire par rapport à la valeur réelle de l''objet, tout en invoquant sa bonne foi totale au moment de cet achat. Cette bonne foi invoquée, aussi sincère puisse-t-elle paraître, se heurte à ce prix manifestement anormal qui aurait pu, voire dû, éveiller ses soupçons sur l''origine douteuse de ce bien.\n\nCette situation pose la question centrale de la connaissance qu''il pouvait ou devait avoir de l''origine frauduleuse de ce vélo au moment de son acquisition, cette question de la connaissance étant déterminante pour la qualification exacte de son comportement dans cette chaîne de transactions.\n\nCette configuration nécessite de recueillir avec précision les circonstances exactes de cette acquisition initiale, sans pour autant présumer d''emblée sa mauvaise foi du seul fait de ce prix anormalement bas qui, à lui seul, ne suffit pas à établir sa connaissance certaine de l''origine du bien.", "questions": [{"position": 1, "max_points": 5, "label": "Comment recueillez-vous précisément les circonstances de cette acquisition pour évaluer sa connaissance réelle de l''origine du bien ?", "hint": "Le prix dérisoire constitue un indice à interroger sans pour autant présumer automatiquement la mauvaise foi de cet acquéreur.", "perfect": "Je l''interroge avec précision sur les circonstances exactes de cette annonce, notamment sa formulation, la présentation du vendeur et les éventuelles justifications données pour ce prix particulièrement bas.\n\nJe recueille ses explications sur les raisons pour lesquelles il n''a pas été alerté par ce prix dérisoire, cette question méritant d''être posée sans pour autant présumer d''emblée qu''il ment sur sa bonne foi.\n\nJe reste attentive aux éléments objectifs qui pourraient confirmer ou contredire sa version, comme la conservation de l''échange avec le vendeur initial ou les modalités de paiement employées.\n\nJe recherche si possible à identifier ce vendeur initial, cette piste étant essentielle pour remonter vers l''origine réelle de ce vol et clarifier la chaîne de responsabilités.", "points": [{"position": 1, "label": "Interroger précisément les circonstances de cette annonce", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : formulation, présentation et justifications du prix.", "groups": [{"position": 1, "keywords": ["circonstances de l''annonce", "formulation interrogée", "justifications du prix"]}]}, {"position": 2, "label": "Recueillir ses explications sur l''absence d''alerte face au prix bas", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Sans présumer d''emblée qu''il ment.", "groups": [{"position": 1, "keywords": ["explications recueillies", "prix dérisoire", "pas de présomption immédiate"]}]}, {"position": 3, "label": "Rester attentive aux éléments objectifs confirmant ou contredisant sa version", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Échange conservé ou modalités de paiement.", "groups": [{"position": 1, "keywords": ["éléments objectifs", "échange conservé", "modalités de paiement"]}]}, {"position": 4, "label": "Rechercher à identifier le vendeur initial", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Remonter vers l''origine réelle du vol.", "groups": [{"position": 1, "keywords": ["vendeur initial recherché", "origine du vol", "chaîne de responsabilités"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment qualifiez-vous précisément son comportement sans présumer automatiquement sa mauvaise foi ?", "hint": "La qualification de recel nécessite d''établir sa connaissance de l''origine frauduleuse, cette connaissance ne pouvant être présumée du seul fait du prix bas.", "perfect": "Je reste attentive à ne pas conclure automatiquement à sa mauvaise foi du seul fait de ce prix anormalement bas, cet élément constituant un indice sérieux sans pour autant suffire à lui seul à établir sa connaissance certaine.\n\nJe recherche des éléments complémentaires qui pourraient confirmer qu''il avait ou aurait dû avoir conscience du caractère probablement frauduleux de cette origine, au-delà du seul prix pratiqué.\n\nJe consigne avec précision l''ensemble de ces éléments pour permettre une qualification juridique appropriée de sa situation, cette qualification devant tenir compte de la globalité du contexte et pas seulement du prix.\n\nJe reste factuelle dans mes constatations, sans exprimer de jugement hâtif sur sa responsabilité avant que l''ensemble des éléments n''ait pu être réuni et analysé.", "points": [{"position": 1, "label": "Ne pas conclure automatiquement à la mauvaise foi du seul fait du prix", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : indice sérieux sans être suffisant à lui seul.", "groups": [{"position": 1, "keywords": ["pas de conclusion automatique", "prix comme indice", "insuffisant seul"]}]}, {"position": 2, "label": "Rechercher des éléments complémentaires confirmant la conscience de l''origine frauduleuse", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Au-delà du seul prix pratiqué.", "groups": [{"position": 1, "keywords": ["éléments complémentaires", "conscience de l''origine", "au-delà du prix"]}]}, {"position": 3, "label": "Consigner l''ensemble des éléments pour une qualification appropriée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Tenir compte de la globalité du contexte.", "groups": [{"position": 1, "keywords": ["éléments consignés", "qualification appropriée", "globalité du contexte"]}]}, {"position": 4, "label": "Rester factuelle sans jugement hâtif sur sa responsabilité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Avant que l''ensemble des éléments soit réuni.", "groups": [{"position": 1, "keywords": ["factuelle sans jugement", "éléments réunis", "pas de hâte"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous la question du bien lui-même et de sa restitution à la victime initiale du vol ?", "hint": "Au-delà de la question de la responsabilité de cet acquéreur, le bien lui-même doit être traité en tenant compte des droits de la victime initiale.", "perfect": "Je m''assure d''identifier la victime initiale de ce vol de vélo, cette personne ayant des droits sur ce bien indépendamment de la question de la responsabilité de l''acquéreur actuel.\n\nJe recueille les éléments permettant d''identifier précisément ce vélo, comme son numéro de série ou toute autre marque distinctive, ces éléments étant nécessaires pour confirmer son lien avec le vol initial.\n\nJe reste attentive aux droits de cet acquéreur qui pourrait lui-même avoir subi un préjudice financier s''il est reconnu de bonne foi, cette dimension méritant d''être prise en compte dans le traitement global de cette affaire.\n\nJe l''informe des suites de cette procédure, notamment sur le sort probable de ce bien et les conséquences possibles pour lui selon l''issue de cette qualification.", "points": [{"position": 1, "label": "Identifier la victime initiale de ce vol de vélo", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : droits sur le bien indépendamment de l''acquéreur.", "groups": [{"position": 1, "keywords": ["victime initiale identifiée", "droits sur le bien", "vol initial"]}]}, {"position": 2, "label": "Recueillir les éléments d''identification précise du vélo", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Numéro de série confirmant le lien avec le vol.", "groups": [{"position": 1, "keywords": ["identification précise", "numéro de série", "lien confirmé"]}]}, {"position": 3, "label": "Rester attentive aux droits de l''acquéreur potentiellement de bonne foi", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Préjudice financier possible à prendre en compte.", "groups": [{"position": 1, "keywords": ["droits de l''acquéreur", "préjudice financier", "bonne foi possible"]}]}, {"position": 4, "label": "Informer des suites et du sort probable du bien", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Conséquences selon l''issue de la qualification.", "groups": [{"position": 1, "keywords": ["suites informées", "sort du bien", "conséquences selon qualification"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-degradation-vehicule-conflit-voisinage', '{"slug": "biens-degradation-vehicule-conflit-voisinage", "title": "Il accuse son voisin sans l''avoir vu faire", "theme_slug": "atteintes-biens", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 9 heures. Un homme vous appelle dans une rue résidentielle pour signaler que son véhicule a été rayé et son rétroviseur cassé durant la nuit, et désigne d''emblée son voisin comme l''auteur certain de ces dégradations, sans toutefois l''avoir vu commettre les faits ni disposer d''aucun élément matériel les reliant directement à cette personne. Cette accusation, formulée avec une conviction absolue, s''appuie exclusivement sur un conflit de voisinage ancien et durable qui alimente sa certitude subjective sur l''identité de l''auteur.\n\nCette situation, où la certitude affichée par la victime repose uniquement sur l''historique conflictuel avec ce voisin plutôt que sur des éléments objectifs et vérifiables, nécessite une vigilance particulière pour ne pas valider prématurément une accusation qui pourrait s''avérer infondée.\n\nCette configuration impose de recueillir avec rigueur les faits matériels constatables tout en évitant de cautionner une désignation d''auteur qui reste, à ce stade, purement subjective et fondée sur un contentieux préexistant entre voisins.", "questions": [{"position": 1, "max_points": 5, "label": "Comment recueillez-vous les faits matériels sans valider prématurément cette accusation fondée sur la seule conviction subjective ?", "hint": "Les constatations doivent rester factuelles et distinctes de l''accusation formulée, cette dernière ne reposant sur aucun élément objectif à ce stade.", "perfect": "Je procède aux constatations matérielles des dégradations constatées sur le véhicule, ces éléments objectifs constituant la seule base solide de mon intervention à ce stade.\n\nJe recueille son récit sur les raisons de sa certitude concernant l''identité de l''auteur, tout en restant attentive au fait que cette certitude repose exclusivement sur un conflit préexistant plutôt que sur une observation directe des faits.\n\nJe ne valide à aucun moment cette accusation par mon attitude ou mes propos, cette réserve étant nécessaire tant qu''aucun élément objectif ne vient la corroborer.\n\nJe l''interroge sur l''existence d''éventuels témoins ou d''éléments de vidéosurveillance qui pourraient objectiver ses soupçons, cette recherche méthodique restant nécessaire avant toute désignation d''un responsable.", "points": [{"position": 1, "label": "Procéder aux constatations matérielles des dégradations", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : éléments objectifs comme seule base solide.", "groups": [{"position": 1, "keywords": ["constatations matérielles", "dégradations constatées", "base objective"]}]}, {"position": 2, "label": "Recueillir son récit en restant attentive au fondement subjectif de sa certitude", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Certitude reposant sur un conflit préexistant.", "groups": [{"position": 1, "keywords": ["récit recueilli", "certitude subjective", "conflit préexistant"]}]}, {"position": 3, "label": "Ne pas valider cette accusation par son attitude ou ses propos", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Réserve nécessaire sans élément objectif corroborant.", "groups": [{"position": 1, "keywords": ["pas de validation", "réserve nécessaire", "sans corroboration"]}]}, {"position": 4, "label": "Interroger sur l''existence de témoins ou de vidéosurveillance", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Objectiver les soupçons avant toute désignation.", "groups": [{"position": 1, "keywords": ["témoins recherchés", "vidéosurveillance", "soupçons objectivés"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment abordez-vous la dimension du conflit de voisinage sans prendre parti dans ce différend ancien ?", "hint": "Ce conflit de voisinage, aussi ancien soit-il, ne doit pas influencer votre traitement objectif de cette dégradation constatée.", "perfect": "Je reste factuelle et neutre face à ce conflit de voisinage qu''il évoque, cette neutralité étant essentielle pour ne pas paraître prendre parti dans un différend qui dépasse le seul cadre de cette dégradation.\n\nJe recueille les grandes lignes de ce conflit pour comprendre le contexte, sans pour autant m''immiscer dans son règlement ou porter un jugement sur les torts respectifs des deux parties.\n\nJe reste attentive à ne pas alimenter ce conflit par mon intervention, mon rôle se limitant strictement au traitement de la dégradation matérielle constatée et non à l''arbitrage du différend sous-jacent.\n\nJe l''informe, si cela semble pertinent, de l''existence de dispositifs de médiation de voisinage qui pourraient utilement compléter le traitement de ce conflit au-delà de la seule question pénale.", "points": [{"position": 1, "label": "Rester factuelle et neutre face à ce conflit de voisinage", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : neutralité essentielle pour ne pas prendre parti.", "groups": [{"position": 1, "keywords": ["neutralité maintenue", "pas de parti pris", "conflit dépassant le cadre"]}]}, {"position": 2, "label": "Recueillir les grandes lignes du conflit sans juger les torts respectifs", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Comprendre le contexte sans s''immiscer.", "groups": [{"position": 1, "keywords": ["contexte compris", "pas de jugement", "torts respectifs"]}]}, {"position": 3, "label": "Ne pas alimenter ce conflit par son intervention", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rôle limité au traitement de la dégradation matérielle.", "groups": [{"position": 1, "keywords": ["conflit non alimenté", "rôle limité", "dégradation traitée"]}]}, {"position": 4, "label": "Informer de l''existence de dispositifs de médiation de voisinage", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Complément au-delà de la seule question pénale.", "groups": [{"position": 1, "keywords": ["médiation informée", "dispositif complémentaire", "au-delà du pénal"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment orientez-vous la suite de cette procédure compte tenu de l''absence d''éléments objectifs contre ce voisin désigné ?", "hint": "L''absence d''éléments objectifs doit orienter la suite de la procédure vers un traitement prudent qui ne présuppose pas la culpabilité du voisin désigné.", "perfect": "Je consigne avec précision les faits constatés et le récit de la victime, en distinguant clairement ce qui relève du fait matériel de ce qui relève de son interprétation subjective sur l''auteur.\n\nJe l''informe que son accusation, en l''état, ne repose pas sur des éléments suffisants pour être retenue contre ce voisin spécifiquement, cette information devant être communiquée avec tact pour ne pas décourager sa plainte légitime.\n\nJe reste attentive à ne pas orienter d''emblée la suite de l''enquête vers ce seul voisin désigné, cette focalisation prématurée risquant de biaiser le traitement objectif de cette affaire.\n\nJe l''informe des suites de cette procédure et de la possibilité que l''enquête n''aboutisse pas à identifier formellement un auteur en l''absence d''éléments plus probants.", "points": [{"position": 1, "label": "Consigner en distinguant le fait matériel de l''interprétation subjective", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : distinction entre fait et interprétation.", "groups": [{"position": 1, "keywords": ["fait matériel distingué", "interprétation subjective", "consignation précise"]}]}, {"position": 2, "label": "Informer avec tact que l''accusation ne repose pas sur des éléments suffisants", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Communication sans décourager la plainte légitime.", "groups": [{"position": 1, "keywords": ["information avec tact", "éléments insuffisants", "plainte non découragée"]}]}, {"position": 3, "label": "Ne pas orienter d''emblée l''enquête vers ce seul voisin désigné", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter une focalisation prématurée biaisant l''enquête.", "groups": [{"position": 1, "keywords": ["pas de focalisation prématurée", "enquête non biaisée", "objectivité maintenue"]}]}, {"position": 4, "label": "Informer de la possibilité que l''enquête n''identifie pas d''auteur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réalisme sur l''issue possible en l''absence d''éléments probants.", "groups": [{"position": 1, "keywords": ["issue réaliste informée", "absence d''éléments probants", "auteur non identifié"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-incendie-volontaire-suspecte', '{"slug": "biens-incendie-volontaire-suspecte", "title": "Le départ de feu est au pied de la cage d''escalier", "theme_slug": "atteintes-biens", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 3 heures. Vous êtes appelée pour un départ de feu dans le local à poubelles d''un immeuble, ce foyer se situant précisément au pied de la cage d''escalier desservant l''ensemble des logements, cette localisation particulière faisant craindre une intention délibérée plutôt qu''un simple accident domestique. Ce feu, bien que rapidement maîtrisé par les services de secours déjà présents à votre arrivée, a généré une fumée dense qui a pu affecter les habitants des étages, certains ayant été réveillés en urgence par cette situation.\n\nCette suspicion d''incendie volontaire, renforcée par cette localisation stratégique au pied de la cage d''escalier qui aurait pu compromettre gravement l''évacuation des habitants en cas de propagation, place la sécurité des occupants de cet immeuble au cœur des priorités immédiates de votre intervention.\n\nCette situation nécessite de concilier l''urgence de sécuriser l''ensemble des habitants de cet immeuble, potentiellement encore exposés à un risque résiduel, avec la préservation d''une scène d''incendie par nature fragile et rapidement dégradée par l''intervention des secours et le passage du temps.", "questions": [{"position": 1, "max_points": 5, "label": "Comment sécurisez-vous en priorité l''ensemble des habitants de cet immeuble avant toute autre considération ?", "hint": "La sécurité des occupants, potentiellement encore exposés à un risque résiduel, doit primer sur toute autre priorité, y compris celle liée aux constatations.", "perfect": "Je m''assure en priorité absolue que l''ensemble des habitants de cet immeuble a bien été évacué ou mis en sécurité, cette vérification restant prioritaire sur toute autre considération à ce stade de l''intervention.\n\nJe coordonne cette vérification avec les services de secours déjà présents, cette collaboration étant essentielle pour couvrir efficacement l''ensemble des étages de cet immeuble.\n\nJe reste attentive aux éventuels signes d''intoxication à la fumée chez les habitants réveillés en urgence, cette vigilance médicale restant nécessaire même après la maîtrise apparente du feu.\n\nJe m''assure que les conditions d''évacuation restent sûres, notamment que la cage d''escalier reste praticable, cette vérification étant cruciale compte tenu de la localisation stratégique de ce départ de feu.", "points": [{"position": 1, "label": "S''assurer en priorité absolue que tous les habitants sont en sécurité", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vérification prioritaire sur toute autre considération.", "groups": [{"position": 1, "keywords": ["habitants en sécurité", "vérification prioritaire", "priorité absolue"]}]}, {"position": 2, "label": "Coordonner cette vérification avec les services de secours présents", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Collaboration essentielle pour couvrir tous les étages.", "groups": [{"position": 1, "keywords": ["coordination avec secours", "étages couverts", "collaboration essentielle"]}]}, {"position": 3, "label": "Rester attentive aux signes d''intoxication à la fumée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance médicale malgré la maîtrise apparente du feu.", "groups": [{"position": 1, "keywords": ["intoxication surveillée", "vigilance médicale", "malgré la maîtrise"]}]}, {"position": 4, "label": "S''assurer que la cage d''escalier reste praticable", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vérification cruciale compte tenu de la localisation stratégique.", "groups": [{"position": 1, "keywords": ["cage d''escalier praticable", "évacuation sûre", "localisation stratégique"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment préservez-vous la scène de cet incendie malgré sa fragilité et le passage des secours ?", "hint": "La scène d''un incendie est par nature fragile et rapidement dégradée, cette préservation devant être organisée dès que la sécurité des personnes est assurée.", "perfect": "Je sécurise le périmètre immédiat du foyer d''incendie dès que possible, cette mesure conservatoire visant à limiter la dégradation supplémentaire d''une scène par nature déjà fragilisée par l''intervention des secours.\n\nJe recueille auprès des services de secours les éléments qu''ils ont pu constater avant et pendant leur intervention, cette information étant précieuse compte tenu de la dégradation rapide de ce type de scène.\n\nJe fais intervenir sans délai les services spécialisés dans les constatations d''incendie, cette rapidité étant nécessaire face à la fragilité particulière de ce type de traces.\n\nJe consigne avec précision l''état des lieux tel que je le découvre à mon arrivée, cette documentation immédiate pouvant compléter utilement les constatations techniques ultérieures.", "points": [{"position": 1, "label": "Sécuriser le périmètre immédiat du foyer d''incendie", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : limiter la dégradation d''une scène fragile.", "groups": [{"position": 1, "keywords": ["périmètre sécurisé", "scène fragile", "dégradation limitée"]}]}, {"position": 2, "label": "Recueillir les éléments constatés par les services de secours", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information précieuse face à la dégradation rapide.", "groups": [{"position": 1, "keywords": ["éléments des secours", "information précieuse", "dégradation rapide"]}]}, {"position": 3, "label": "Faire intervenir sans délai les services spécialisés en incendie", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rapidité nécessaire face à la fragilité des traces.", "groups": [{"position": 1, "keywords": ["services spécialisés", "intervention sans délai", "fragilité des traces"]}]}, {"position": 4, "label": "Consigner précisément l''état des lieux dès l''arrivée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Documentation complétant les constatations techniques.", "groups": [{"position": 1, "keywords": ["état des lieux consigné", "documentation immédiate", "constatations complétées"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment recueillez-vous les éléments auprès des habitants pour orienter l''enquête sur cette suspicion d''acte volontaire ?", "hint": "Les habitants, réveillés en urgence, peuvent détenir des informations précieuses sur les circonstances précédant ce départ de feu suspect.", "perfect": "Je recueille auprès des habitants réveillés en urgence tout élément qu''ils auraient pu observer avant ou pendant ce départ de feu, comme des bruits suspects ou la présence de personnes inconnues dans l''immeuble.\n\nJe m''intéresse particulièrement à un éventuel contexte conflictuel au sein de cet immeuble qui pourrait expliquer cette suspicion d''acte volontaire visant ce lieu de passage commun.\n\nJe reste attentive à recueillir ces témoignages avec tact, ces habitants étant encore sous le choc de ce réveil brutal et de l''inquiétude légitime que cette situation a pu susciter.\n\nJe transmets l''ensemble de ces éléments aux services compétents pour l''enquête sur cette suspicion d''incendie volontaire, cette transmission complétant utilement les constatations techniques réalisées sur place.", "points": [{"position": 1, "label": "Recueillir les observations des habitants sur les circonstances précédant le feu", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : bruits suspects ou personnes inconnues.", "groups": [{"position": 1, "keywords": ["observations recueillies", "bruits suspects", "personnes inconnues"]}]}, {"position": 2, "label": "S''intéresser à un éventuel contexte conflictuel dans l''immeuble", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Explication possible de cette suspicion d''acte volontaire.", "groups": [{"position": 1, "keywords": ["contexte conflictuel", "acte volontaire suspecté", "explication recherchée"]}]}, {"position": 3, "label": "Recueillir ces témoignages avec tact face au choc des habitants", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Habitants sous le choc du réveil brutal.", "groups": [{"position": 1, "keywords": ["tact nécessaire", "choc des habitants", "réveil brutal"]}]}, {"position": 4, "label": "Transmettre l''ensemble des éléments aux services compétents", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Compléter les constatations techniques réalisées.", "groups": [{"position": 1, "keywords": ["éléments transmis", "services compétents", "constatations complétées"]}]}]}]}'::jsonb);
